-- FLL-GAR-2023 · coverage wave block 5b (2026-09-30): gates on the block-5a fields + the plant-register Tab.-29 proposal. SIGN-OFF REQUIRED.
-- Apply after 5a and after the rulings: node scripts/apply-migration.mjs scripts/migrations/20260930100100_fll_gar_2023_gates_coverage_block5b.sql
-- Rollback: scripts/migrations/rollback-20260930100100_fll_gar_2023_gates_coverage_block5b.sql
BEGIN;
-- FLL-GAR-17 REQ-41 (new, block) — "muss … entsprechen" / "Es müssen Einlagen …" → block (RULING: severity). Reads the existing fk_trockenschichtdicke; the Tab.-23 fills are keyed on fk_stoff_tab23.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-41', 'Flüssigkunststoff — Schichtdicke ≥ Tab. 23 / ETA und Einlage ≥ 110 g/m² (§6.3.1.2, §6.3.2)', 'Liquid-applied plastic — layer thickness ≥ Tab. 23 / ETA and insert ≥ 110 g/m² (§6.3.1.2, §6.3.2)', 'IF abdichtungs_art == fluessigkunststoff THEN fk_trockenschichtdicke >= fk_schichtdicke_min_mm AND (fk_eta_mindestschichtdicke_mm IS NULL OR fk_trockenschichtdicke >= fk_eta_mindestschichtdicke_mm) AND fk_einlage_g_m2 >= fk_einlage_min_g_m2', 'Sec.6.3.1.2; Sec.6.3.2; Tab.23', 'block', 'Coverage block 5b (2026-09-30): "muss … entsprechen" / "Es müssen Einlagen …" → block (RULING: severity). Reads the existing fk_trockenschichtdicke; the Tab.-23 fills are keyed on fk_stoff_tab23.', 'Die Mindestschichtdicke der ausgehärteten flüssigen Abdichtung muss den Angaben der Zulassung (ETA, AbP gemäß MVV TB) entsprechen. Sie beträgt gemäß Tabelle 23 mind. 2,0 mm. Wenn die in der ETA angegebene Mindestschichtdicke höher ist, gilt der höhere Wert. Abdichtungen mit Flüssigkunststoffen werden i. d. R. vollflächig haftend und mindestens zweischichtig (Träger-, Deckschicht) mit Einlage ausgeführt. Dies kann durch Streichen, Rollen oder Spritzen erfolgen. Es müssen Einlagen (z. B. Glasvlies, Polyestervlies) mit einem Flächengewicht von mind. 110 g/m² eingesetzt werden.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-17' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-14 REQ-42 (new, block) — Tab. 15 rows 8–11 are "festgelegte Mindestanforderungen" for every product; rows 2–7 "können produktabhängig abweichen" and are NOT gated (their values are in TAB15 for reference). Block (RULING: severity).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-42', 'GTD — Geotextil MA ≥ Tab. 14 und Tab.-15-Mindestanforderungen Zeilen 8–11', 'GCL — geotextile MA ≥ Tab. 14 and Tab. 15 minimum requirements rows 8–11', 'IF abdichtungs_art == verbundwerkstoff_gtd THEN gtd_geotextil_flaecheneinheit_g_m2 >= gtd_geotextil_flaecheneinheit_min AND gtd_zugfestigkeit_kn_m >= 10 AND gtd_zugfestigkeitsdehnung_pct <= 30 AND gtd_verbundfestigkeit_n_m >= 360 AND gtd_kf_m_s <= 5e-11 AND gtd_permittivitaet_m_s <= 5e-9', 'Sec.5.5.1.1; Tab.14; Tab.15', 'block', 'Coverage block 5b (2026-09-30): Tab. 15 rows 8–11 are "festgelegte Mindestanforderungen" for every product; rows 2–7 "können produktabhängig abweichen" and are NOT gated (their values are in TAB15 for reference). Block (RULING: severity).', 'Die eingesetzten Geotextilien sollen gleichzeitig widerstandsfähig gegenüber Einbaubeanspruchungen sein. Anforderungswerte an die Eigenschaften der Geotextilien werden in Tabelle 14 angegeben. Die Anforderungen in den Zeilen 2 bis 7 der Tabelle 15 können produktabhängig abweichen. Für andere Verbindungsverfahren, Bentonitarten und Oberflächenausbildungen gelten hinsichtlich Zugfestigkeit, Zugfestigkeitsdehnung, Verbundfestigkeit, Durchlässigkeitsbeiwert (kf) und Permittivität die in den Zeilen 8 bis 11 festgelegten Mindestanforderungen.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-14' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-12 REQ-43 (new, block) — "müssen eingehalten werden" → block; the lower limit comes from the Tab.-9 case (5 °C / 10 °C), the upper limit + 30 °C from the sentence.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-43', 'Frischbetontemperatur — mindestens Tab. 9, höchstens + 30 °C (§5.3.2.1)', 'Fresh-concrete temperature — at least Tab. 9, at most + 30 °C (§5.3.2.1)', 'IF abdichtungs_art == mineralisch_hydraulisch THEN frischbeton_temperatur_c >= frischbeton_temp_min_c AND frischbeton_temperatur_c <= 30', 'Sec.5.3.2.1; Tab.9', 'block', 'Coverage block 5b (2026-09-30): "müssen eingehalten werden" → block; the lower limit comes from the Tab.-9 case (5 °C / 10 °C), the upper limit + 30 °C from the sentence.', 'Bei extrem niedrigen oder hohen Lufttemperaturen ist die Betontemperatur zu überwachen. Die Grenztemperaturen des Frischbetons nach DIN 1045-3 von mind. + 5 °C bzw. höchstens + 30 °C müssen eingehalten werden, um eine bleibende Beeinträchtigung der Frischbetoneigenschaften zu vermeiden (s. Tab. 9).', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-12' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-24 pflanzenarten register (D-15 / D-20): optional column "Art nach Tab. 29" (lookup_key TAB29) + derived tab29_flag; the engineer's own
-- "aggressiv" flag stays (Tab. 29 prints EXAMPLES — "Beispiele von Pflanzen mit aggressiven Wurzeln oder Rhizomen"). RULING: D-20 (which C1 species get the flag).
UPDATE fields f SET ui_config = jsonb_set(f.ui_config, '{columns}', '[{"key":"art","type":"text","label":"Pflanzenart","required":true},{"key":"tab29_art","type":"lookup_key","label":"Art nach Tab. 29 (falls gelistet)","lookup":{"table_code":"TAB29"}},{"key":"tab29_flag","type":"derived","label":"in Tab. 29","expr":"if(tab29_art IS NULL, 0, 1)","display":"badge","value_labels":{"0":"nicht in Tab. 29","1":"Tab. 29: aggressive Wurzeln / Rhizome"}},{"key":"aggressiv","type":"boolean","label":"aggressiv wurzelnd / rhizombildend (Fachplaner)"}]'::jsonb),
  description = COALESCE(f.description, '') || ' — Coverage block 5b (2026-09-30): Tab.-29 column added (TAB29, block 1).'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLL-GAR-24' AND s.code = 'FLL-GAR-2023' AND f.symbol = 'pflanzenarten' AND NOT (f.ui_config->'columns')::text LIKE '%tab29_art%';
UPDATE equations e SET formula = 'pflanzen_aggressiv_count = count_rows(pflanzenarten, aggressiv == true OR tab29_flag == 1)', description = COALESCE(e.description, '') || ' — Coverage block 5b (2026-09-30): counts the engineer flag OR a Tab.-29 match.', verification_quote = 'Bei Verwendung oder Vorhandensein derartiger Pflanzenarten sind über den Standardaufbau der Abdichtung hinausgehende bauliche Vorkehrungen, z. B. als Rhizom- und Wurzelsperre, zu treffen und besondere Pflegemaßnahmen vorzusehen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND w.code = 'FLL-GAR-24' AND s.code = 'FLL-GAR-2023' AND e.equation_number = 'FLL-GAR-24-D2' AND e.formula = 'pflanzen_aggressiv_count = count_rows(pflanzenarten, aggressiv == true)';
COMMIT;
